#!/bin/sh
cd "$(dirname "$0")" && python3 checklang.py && mcs -sdk:4.5 -target:winexe -optimize+ -platform:anycpu -out:build/FileConverter.exe -win32icon:assets/app.ico -resource:assets/logo.png,FileConverter.logo.png -resource:assets/logo_silver.png,FileConverter.logo_silver.png -resource:assets/logo_dark.png,FileConverter.logo_dark.png -r:System.Windows.Forms.dll -r:System.Drawing.dll -r:System.IO.Compression.dll -r:System.IO.Compression.FileSystem.dll -r:System.Core.dll -r:System.Xml.dll -r:Accessibility.dll src/*.cs && cp build/FileConverter.exe "build/Fadi Tools.exe"
